tasks.for:
('grow.tend' in viewer.grants and (item.state = 'offered' or (item.state = 'taken' and item.performer = viewer.member))) ? (
  $ownMember := viewer.member;
  $currentScope := scope;
  $roomRows := reads.site.sources.room[fields.scope = $currentScope];
  $ownPresence := reads.presence.sources.people[fields.member = $ownMember];
  $count($ownPresence) = 1 and $count($roomRows) = 1 ? (
    $ownPresence.state = 'unknown' ? null : (
      $ownPresence.state = 'away' ? false : ($ownPresence.state = 'present' ? $ownPresence.fields.room = $roomRows.id : null)
    )
  ) : null
) : false
